export function evaluate({ inputs, time }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = 9.8;
  const t = time;
  const velocity = launchSpeed - gravity * t;
  const height = launchSpeed * t - 0.5 * gravity * t * t;
  const maxH = (launchSpeed * launchSpeed) / (2 * gravity);
  const scaleY = 250 / Math.max(2.5, maxH * 1.2);
  const baseY = 320;
  const ballY = baseY - height * scaleY;
  const ballX = 320;

  const lane = sdk.panel({ x: 80, y: 50, w: 480, h: 320, title: "Vertical Toss", state: "Time: " + sdk.format(t, 2) + " s" });
  const axis = sdk.axis("axis.height", { x: 120, y: 320, length: 260, orientation: "y", min: 0, max: Math.max(1.5, maxH * 1.2), ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m" });
  const guide = sdk.groundMark("ground.launch", ballX, baseY, 60, "Launch");

  const ball = sdk.circle("ball.toss", ballX, ballY, 28, { role: "output" });

  const vArrows = Math.abs(velocity) > 0.05 ? [sdk.vector("vec.v", { x: ballX + 20, y: ballY }, { value: velocity, direction: "up" }, { scale: 15, minLength: 12, label: "v" })] : [];
  const gArrow = [sdk.vector("vec.a", { x: ballX - 20, y: ballY }, { value: -gravity, direction: "up" }, { scale: 8, minLength: 12, label: "Fg" })];

  let motionStateText = "Moving up";
  if (Math.abs(velocity) <= 0.05) {
    motionStateText = "Still for an instant";
  } else if (velocity < 0) {
    motionStateText = "Moving down";
  }

  const calloutLines = [motionStateText, "Gravity pulls down"];
  const callout = sdk.callout(ballX + 45, ballY - 20, calloutLines, { id: "callout.toss" });

  const objects = [lane, axis, guide, ball, ...vArrows, ...gArrow, callout];

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "motionState", value: motionStateText },
        { id: "gravityState", value: "Pulling down" }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime: launchSpeed / gravity,
      apexHeight: maxH,
      velocity,
      height
    }
  };
}
